def roda_dari_perintah(v, w, r, l):
    return (2 * v + w * l) / (2 * r), (2 * v - w * l) / (2 * r)


def odometri(pose, wr, wl, r, l, dt):
    x, y, th = pose
    v = r * (wr + wl) / 2
    w = r * (wr - wl) / l
    return x + v * math.cos(th) * dt, y + v * math.sin(th) * dt, th + w * dt


def normalisasi_sudut(a):
    while a > math.pi:
        a -= 2 * math.pi
    while a <= -math.pi:
        a += 2 * math.pi
    return a


def jarak_dan_sudut(pose, target):
    x, y, th = pose
    dx, dy = target[0] - x, target[1] - y
    return math.hypot(dx, dy), normalisasi_sudut(math.atan2(dy, dx) - th)


def perintah_menuju(pose, target):
    jarak, selisih = jarak_dan_sudut(pose, target)
    if jarak < 0.05:
        return 0.0, 0.0
    v = 0.0 if abs(selisih) > 0.5 else min(0.5, jarak)
    return v, 2.0 * selisih


def simulasi(pose, target, langkah=2000, dt=0.05):
    for _ in range(langkah):
        if jarak_dan_sudut(pose, target)[0] < 0.05:
            break
        v, w = perintah_menuju(pose, target)
        wr, wl = roda_dari_perintah(v, w, R, L)
        pose = odometri(pose, wr, wl, R, L, dt)
    return pose

