from collections import deque


def langkah_terpendek(grid, awal, tujuan):
    antre = deque([(awal, 0)])
    lihat = {awal}
    while antre:
        (r, c), d = antre.popleft()
        if (r, c) == tujuan:
            return d
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            b, k = r + dr, c + dc
            if 0 <= b < len(grid) and 0 <= k < len(grid[0]) and grid[b][k] == 0 and (b, k) not in lihat:
                lihat.add((b, k))
                antre.append(((b, k), d + 1))
    return -1
